<script setup>
import {ref,reactive,onMounted,watch} from 'vue';
import {commerceRequest} from './commerce-api';
const props=defineProps({endpoint:String,token:String,connected:Boolean,refreshKey:Number});
const orders=ref([]),inventory=ref([]),busy=ref(false),error=ref(''),message=ref(''),view=ref('inbox'),status=ref('all');
const nextCursor=ref(''),total=ref(0),summary=ref({}),search=ref(''),dateFrom=ref(''),dateTo=ref(''),exportKind=ref('orders');
const drafts=reactive({});
const lanes=[['inbox','To order / send','↘'],['progress','In progress','↗'],['shipped','Shipped','✓'],['attention','Needs attention','!'],['all','All orders','≡']];
const names={keycaps:'Custom keycaps',aliexpress:'AliExpress',mouser:'Mouser',office:'RODDY shipment',printify:'Printify'};
const ready=f=>['ready-to-order','awaiting-submission','ready-to-ship'].includes(f.state);
const label=f=>ready(f)?f.kind==='office'?'Ready to ship':'Place supplier order':f.state==='submitted'?'Ordered · waiting for dispatch':f.state==='shipped'?'Shipped':f.state.replaceAll('-',' ');
const money=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format((n || 0)/100);
const date=n=>new Date(n*1000).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const request=(path,body)=>commerceRequest(props.endpoint,path,props.token,body);
function filters(){return {view:view.value,status:status.value,search:search.value,start:dateFrom.value?Math.floor(new Date(dateFrom.value+'T00:00:00').getTime()/1000):0,end:dateTo.value?Math.floor(new Date(dateTo.value+'T00:00:00').getTime()/1000)+86400:0};}
async function refresh(){const data=await request('/admin/orders?'+new URLSearchParams(filters()));orders.value=data.data;nextCursor.value=data.next_cursor || '';total.value=data.total ?? data.data.length;summary.value=data.summary || {};}
async function run(fn){busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
const load=()=>run(refresh);
function lane(id){view.value=id;status.value='all';load();}
function more(){return run(async()=>{const data=await request('/admin/orders?'+new URLSearchParams({...filters(),cursor:nextCursor.value}));orders.value.push(...data.data);nextCursor.value=data.next_cursor || '';});}
async function download(path,filename,body={}){const response=await fetch(props.endpoint.replace(/\/$/,'')+path,{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+props.token},body:JSON.stringify(body)});if(!response.ok)throw new Error((await response.json()).error || 'Download failed.');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function packet(order,kind){return run(()=>download('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),'RODDY-'+order.id+'-'+kind+'.zip',{action:'download',kind}));}
function pendingPackets(){return run(()=>download('/admin/keycaps/packets','RODDY-pending-keycap-orders.zip'));}
function exportRecords(){return run(()=>download('/admin/orders/export','RODDY-'+exportKind.value+'.csv',{...filters(),view:'all',kind:exportKind.value}));}
function syncRecords(){return run(async()=>{let cursor='',checked=0;do{const data=await request('/admin/orders/sync',{...filters(),cursor});checked+=data.checked;cursor=data.next_cursor || '';}while(cursor);await refresh();message.value=checked+' payment records checked with Square.';});}
function orderDraft(order,kind){const fulfillment=order.fulfillments.find(f=>f.kind===kind),tracking=fulfillment?.shipments?.at(-1);return drafts[order.id+':'+kind] ||= {reference:fulfillment?.supplierId || '',amount:'',carrier:tracking?.carrier || '',number:tracking?.number || '',url:tracking?.url || ''};}
async function invoice(order,kind,ref,amount){if(!amount)return;await request('/admin/orders/'+order.id+'/expenses',{supplier:names[kind],reference:ref,amountCents:Math.round(Number(amount)*100),currency:'USD',date:new Date().toLocaleDateString('en-CA'),note:''});}
function ordered(order,kind){return run(async()=>{const d=orderDraft(order,kind);if(!d.reference.trim())throw new Error('Add the supplier order number so you can find it later.');await request('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),{action:kind==='keycaps'?'submitted':'ordered',kind,supplierReference:d.reference});try{await invoice(order,kind,d.reference,d.amount);}finally{await refresh();}message.value='Ordered ✓ Next stop: dispatch and tracking.';});}
function pending(order,kind){return run(async()=>{await request('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),{action:'pending',kind});await refresh();message.value='Back in your inbox.';});}
function shipment(order,kind){return run(async()=>{const d=orderDraft(order,kind);await request('/admin/orders/'+order.id+'/shipment',{kind,carrier:d.carrier,number:d.number,url:d.url});await refresh();message.value='On its way ✓ Tracking is saved for the customer.';});}
function reconcile(order){return run(async()=>{await request('/admin/orders/'+order.id+'/reconcile',{});await refresh();});}
function cancel(order){return run(async()=>{await request('/admin/orders/'+order.id+'/cancel',{});await refresh();message.value='Unpaid checkout canceled.';});}
function addressText(a){return a?[a.first_name+' '+a.last_name,a.address1,a.address2,a.city+', '+a.region+' '+a.zip,a.country,a.phone,a.email].filter(Boolean).join('\n'):'';}
function copy(value){return run(async()=>{await navigator.clipboard.writeText(value);message.value='Copied. Ready to paste.';});}
function expenseDraft(order){return drafts['expense:'+order.id] ||= {supplier:'',reference:'',amount:'',date:new Date().toLocaleDateString('en-CA'),note:''};}
function addExpense(order){return run(async()=>{const d=expenseDraft(order);await request('/admin/orders/'+order.id+'/expenses',{...d,amountCents:Math.round(Number(d.amount)*100),currency:'USD'});delete drafts['expense:'+order.id];await refresh();message.value='Invoice recorded ✓';});}
function loadInventory(){return run(async()=>{const data=await request('/admin/inventory');inventory.value=data.items;for(const i of inventory.value)drafts['stock:'+i.id]=i.stock;});}
function stock(item){return run(async()=>{await request('/admin/inventory/'+encodeURIComponent(item.id),{stock:Number(drafts['stock:'+item.id])});const data=await request('/admin/inventory');inventory.value=data.items;message.value='Stock saved.';});}
watch(()=>props.refreshKey,()=>{if(props.connected)load();});
watch(()=>props.connected,connected=>{if(connected)load();else{orders.value=[];inventory.value=[];}});
onMounted(()=>{if(props.connected)load();});
</script>
<template>
  <section class="order-manager">
    <header class="order-desk-heading"><div><p class="desk-eyebrow">RODDY / ORDER DESK <span class="live-dot" /></p><h2>LET’S GET THESE MOVING<span>.</span></h2><p>New orders in. Happy keyboards out.</p></div><button class="button small" :disabled="busy || !connected" @click="load">{{busy?'Working…':'Refresh ↻'}}</button></header>
    <div class="order-scoreboard"><div><small>TO ORDER / SEND</small><strong>{{summary.inbox || 0}}</strong></div><div><small>IN PROGRESS</small><strong>{{summary.progress || 0}}</strong></div><div><small>SHIPPED</small><strong>{{summary.shipped || 0}}</strong></div><div class="sales-score"><small>RECORDED SALES</small><strong>{{money(summary.capturedCents)}}</strong><span v-if="summary.refundedCents">{{money(summary.refundedCents)}} refunded</span></div></div>
    <nav class="order-lanes" aria-label="Order workflow"><button v-for="[id,title,icon] in lanes" :key="id" :aria-pressed="view===id" :disabled="busy" @click="lane(id)"><b>{{icon}}</b>{{title}}<span>{{summary[id] || 0}}</span></button><button :aria-pressed="view==='keycaps'" :disabled="busy" @click="lane('keycaps')">Keycap orders</button></nav>
    <div class="order-search"><input v-model="search" type="search" aria-label="Search orders" placeholder="Find an order, reference or customer…" @keydown.enter="load" /><button class="button small" :disabled="busy" @click="load">Find →</button><label>Payment<select v-model="status" aria-label="Payment status" @change="load"><option value="all">All statuses</option><option value="paid">Paid</option><option value="refunded">Refunded</option><option value="partially-refunded">Partially refunded</option><option value="unconfirmed">Unconfirmed</option><option value="canceled">Canceled</option><option value="processing">Processing</option><option value="failed">Failed</option></select></label></div>
    <p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="message" class="desk-success" role="status">{{message}}</p>
    <div class="order-cards"><article v-for="order in orders" :key="order.id" class="order-card" :class="{unpaid:order.payment_status!=='paid'}">
      <header class="order-card-heading"><div><button class="order-number" title="Copy full order reference" @click="copy('RODDY-'+order.id)">#{{order.id.slice(-8).toUpperCase()}} ↗</button><p>{{date(order.created)}} <span v-if="order.address">· {{order.address.first_name}} {{order.address.last_name}}</span></p></div><div class="order-total"><strong>{{money(order.amount_total)}}</strong><span class="payment-chip" :class="order.payment_status">{{order.payment_status.replaceAll('-',' ')}}</span></div></header>
      <ul class="order-items"><li v-for="(item,index) in order.items" :key="index"><b class="quantity-pill">{{item.qty}}×</b><div><strong>{{item.name}}</strong><details v-if="item.label"><summary>Design / options</summary><p>{{item.label}}</p></details><p v-if="item.supplier" class="supplier-part">{{names[item.kind]}} · {{item.supplier.supplierSku}}<span v-if="item.supplier.variantId"> · SKU {{item.supplier.variantId}}</span><a v-if="item.supplier.productUrl?.startsWith('https://')" :href="item.supplier.productUrl" target="_blank" rel="noopener noreferrer">Open exact listing ↗</a></p></div></li></ul>
      <div v-if="order.address" class="delivery-card"><div><small>SHIP TO</small><address>{{order.address.first_name}} {{order.address.last_name}}<br />{{order.address.address1}} {{order.address.address2}}<br />{{order.address.city}}, {{order.address.region}} {{order.address.zip}} · {{order.address.country}}</address><p>{{order.address.email}} · {{order.address.phone}}</p></div><button type="button" :disabled="busy" @click="copy(addressText(order.address))">Copy address ⧉</button></div>
      <section v-for="f in order.fulfillments" :key="f.kind" class="fulfillment-step"><div class="step-heading"><strong>{{names[f.kind] || f.kind}}</strong><span class="step-chip" :class="{done:['shipped','delivered'].includes(f.state),next:ready(f)}">{{label(f)}}</span></div><p v-if="f.error" class="notice">{{f.error}}</p><p v-if="f.supplierId" class="supplier-reference">Supplier reference: {{f.supplierId}}</p>
        <template v-if="order.payment_status==='paid'">
          <div v-if="['keycaps','aliexpress','mouser'].includes(f.kind) && ready(f)" class="next-action"><p class="step-caption">01 / PLACE THE ORDER</p><button class="button primary small" :disabled="busy" @click="packet(order,f.kind)">{{f.kind==='keycaps'?'Download design JSON & order details ↓':'Download supplier order details ↓'}}</button><p v-if="f.kind==='keycaps'" class="small-help">Includes the design, quantity and delivery details.</p><form class="order-confirm-form" @submit.prevent="ordered(order,f.kind)"><label>Supplier order number<input v-model="orderDraft(order,f.kind).reference" maxlength="150" placeholder="Paste the reference after ordering" required /></label><label>Actual supplier total · USD <small>optional</small><input v-model="orderDraft(order,f.kind).amount" type="number" min="0.01" step="0.01" placeholder="Invoice total" /></label><button class="button small" :disabled="busy">Mark ordered ✓</button></form></div>
          <div v-if="f.kind==='printify'" class="printify-actions"><a class="button small" href="https://printify.com/app/orders" target="_blank" rel="noopener noreferrer">Open production orders ↗</a><button v-if="f.state==='review'" class="button small" :disabled="busy" @click="reconcile(order)">Find existing production order</button></div>
          <details v-if="['office','keycaps','aliexpress','mouser'].includes(f.kind) && (!ready(f) || f.kind==='office')" class="tracking-editor" :open="f.state!=='shipped'"><summary>{{f.state==='shipped'?'Update tracking':'02 / SEND IT ON ITS WAY'}}</summary><form class="form-grid" @submit.prevent="shipment(order,f.kind)"><label>Carrier<input v-model="orderDraft(order,f.kind).carrier" placeholder="USPS, UPS, DHL…" required /></label><label>Tracking number<input v-model="orderDraft(order,f.kind).number" required /></label><label class="full">Tracking link <small>optional</small><input v-model="orderDraft(order,f.kind).url" type="url" /></label><button class="button primary small" :disabled="busy">Save tracking + mark shipped ✓</button></form></details>
          <button v-if="f.state==='submitted' && ['keycaps','aliexpress','mouser'].includes(f.kind)" class="undo-action" :disabled="busy" @click="pending(order,f.kind)">Undo: back to inbox</button>
        </template>
        <div v-for="shipment in f.shipments" :key="shipment.number" class="tracking-receipt"><b>↗ {{shipment.carrier}}</b><span>{{shipment.number}}</span><a v-if="shipment.url" :href="shipment.url" target="_blank" rel="noopener noreferrer">Track package →</a></div>
      </section>
      <p v-if="order.payment_status==='paid' && !order.fulfillments.length" class="digital-done">✓ Digital download · available on the customer’s order page</p>
      <button v-if="order.payment_status==='unconfirmed'" class="undo-action" :disabled="busy" @click="cancel(order)">Cancel unpaid checkout</button>
      <details class="order-accounting"><summary>Payment & invoice records</summary><p v-if="order.finance">Captured {{money(order.finance.captured)}} · Refunded {{money(order.finance.refunded)}} · Fees {{order.finance.fees===null?'not yet reported':money(order.finance.fees)}}<span v-if="order.finance.netAfterFees!==null"> · Net {{money(order.finance.netAfterFees)}}</span></p><p>Square reference: {{order.providerId || 'Not created'}}</p><p v-for="expense in order.expenses || []" :key="expense.id">{{expense.incurred}} · {{expense.supplier}} · {{expense.reference}} · {{money(expense.amount,expense.currency)}}</p><details><summary>Add a supplier invoice</summary><form class="form-grid" @submit.prevent="addExpense(order)"><label>Supplier<input v-model="expenseDraft(order).supplier" required /></label><label>Invoice reference<input v-model="expenseDraft(order).reference" required /></label><label>Invoice date<input v-model="expenseDraft(order).date" type="date" required /></label><label>Actual total · USD<input v-model="expenseDraft(order).amount" type="number" min="0.01" step="0.01" required /></label><label class="full">Note<input v-model="expenseDraft(order).note" maxlength="500" /></label><button class="button small" :disabled="busy">Record invoice</button></form></details></details>
    </article></div>
    <div v-if="!orders.length && !busy" class="order-empty"><b>✓</b><h3>{{view==='inbox'?'All caught up.':'Nothing here yet.'}}</h3><p>{{view==='inbox'?'New paid orders land here, ready for your next move.':'Try another view or clear your search.'}}</p></div>
    <button v-if="nextCursor" class="button small" :disabled="busy" @click="more">Load more orders ↓</button><p class="loaded-count">{{orders.length}} of {{total}} matching orders</p>
    <details class="desk-reports"><summary>Reports, CSV exports & tools ↗</summary><div class="form-grid"><label>From<input v-model="dateFrom" type="date" /></label><label>Through<input v-model="dateTo" type="date" /></label><button class="button small" :disabled="busy" @click="load">Apply dates</button><label>Export<select v-model="exportKind"><option value="orders">Order summary</option><option value="items">Line items</option><option value="expenses">Supplier expenses</option><option value="payments">Payment history</option></select></label><button class="button small" :disabled="busy || !connected" @click="exportRecords">Download CSV ↓</button><button class="button small" :disabled="busy || !connected" @click="syncRecords">Refresh payment records</button><button class="button small" :disabled="busy || !connected" @click="pendingPackets">Download next 100 keycap packets ↓</button><a class="button small" href="https://squareup.com/dashboard/sales/transactions" target="_blank" rel="noopener noreferrer">Square receipts & refunds ↗</a></div><p class="small-help">CSV exports include every matching order, with UTC timestamps. Blank fees or tax have not been verified. Exports cover all workflow stages using your dates, search and payment filter. Supplier expenses use their invoice currency.</p></details>
    <details class="desk-reports" @toggle="e=>{if(e.target.open && !inventory.length)loadInventory()}"><summary>Stock you ship from RODDY</summary><div class="product-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Available</th><th>Reserved</th><th>On hand</th><th /></tr></thead><tbody><tr v-for="item in inventory" :key="item.id"><td>{{item.name}}</td><td>{{item.available}}</td><td>{{item.reserved}}</td><td><input v-model="drafts['stock:'+item.id]" type="number" min="0" :aria-label="`On-hand stock for ${item.name}`" /></td><td><button class="button small" :disabled="busy" @click="stock(item)">Save stock</button></td></tr></tbody></table></div></details>
  </section>
</template>
<style scoped>
.order-manager{--desk-blue:#93B0DB;--desk-red:#DB3537}.order-desk-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:28px}.desk-eyebrow{font:11px monospace;letter-spacing:2px;margin-bottom:12px}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#79bd89;margin-left:8px;box-shadow:0 0 12px #79bd89aa}.order-desk-heading h2{font-size:clamp(28px,4vw,48px);font-weight:900;line-height:1.05;max-width:600px;margin:0 0 12px}.order-desk-heading h2 span{color:var(--desk-red)}.order-desk-heading>div>p:last-child{font-size:14px;opacity:.7}.order-scoreboard{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:24px}.order-scoreboard>div{padding:20px;border:1px solid var(--color-border,#444);border-top:3px solid var(--desk-blue)}.order-scoreboard small{display:block;font:10px monospace;letter-spacing:1px;margin-bottom:12px}.order-scoreboard strong{font-size:36px;font-weight:900;line-height:1.1;display:block}.order-scoreboard .sales-score strong{font-size:clamp(21px,2.5vw,36px)}.order-scoreboard span{display:block;font-size:11px;margin-top:6px;opacity:.7}.order-lanes{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.order-lanes button{display:flex;align-items:center;gap:9px;padding:11px 14px;border:1px solid var(--color-border,#444);font-size:12px}.order-lanes button[aria-pressed=true]{background:var(--desk-blue);color:#181c24;border-color:var(--desk-blue)}.order-lanes b{font-size:17px}.order-lanes span{font:11px monospace;border:1px solid currentColor;border-radius:20px;min-width:21px;padding:2px 5px;text-align:center}.order-search{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:24px}.order-search>input{flex:1;min-width:220px}.order-search input,.order-search select,.order-confirm-form input{padding:11px;border:1px solid var(--color-border,#444);background:var(--color-panel,transparent);border-radius:5px;min-width:0}.order-search label{display:flex;align-items:center;gap:9px;font-size:12px}.desk-success{padding:14px 18px;background:#79bd8918;border:1px solid #79bd8966;font-size:14px;margin:18px 0}.order-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}.order-card{border:1px solid var(--color-border,#444);border-top:4px solid var(--desk-blue);padding:24px;border-radius:4px;overflow-wrap:anywhere}.order-card.unpaid{border-top-color:#777}.order-card-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;border-bottom:1px solid var(--color-border,#444);padding-bottom:18px}.order-number{font:700 19px monospace;letter-spacing:1px;text-align:left}.order-card-heading p{font-size:12px;opacity:.7;margin-top:8px;line-height:1.6}.order-total{text-align:right;flex-shrink:0}.order-total>strong{font-size:24px;display:block;margin-bottom:7px}.payment-chip{font:10px monospace;border:1px solid #777;padding:4px 8px;border-radius:20px;text-transform:uppercase;display:inline-block}.payment-chip.paid{border-color:#79bd89;color:#79bd89}.payment-chip.refunded,.payment-chip.partially-refunded{border-color:#d39b68;color:#d39b68}.order-items{list-style:none;margin:20px 0;padding:0;display:grid;gap:16px}.order-items li{display:flex;align-items:flex-start;gap:12px}.quantity-pill{padding:8px 10px;border:1px solid var(--desk-blue);color:var(--desk-blue);font:700 15px monospace}.order-items strong{font-size:15px}.order-items details{font-size:11px;margin-top:6px;line-height:1.6}.supplier-part{font:10px monospace;opacity:.8;line-height:1.8;margin-top:8px}.supplier-part a{display:block;text-decoration:underline}.delivery-card{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;background:#93b0db0c;border:1px solid #93b0db33;padding:16px;margin:18px 0}.delivery-card small{font:10px monospace;letter-spacing:1px;color:var(--desk-blue)}.delivery-card address{font-style:normal;font-size:13px;line-height:1.7;margin-top:8px}.delivery-card p{font-size:11px;line-height:1.6;margin-top:8px}.delivery-card button{font-size:11px;text-decoration:underline;flex-shrink:0}.fulfillment-step{border-top:1px solid var(--color-border,#444);padding-top:18px;margin-top:18px}.step-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.step-heading>strong{font-size:14px}.step-chip{font:10px monospace;text-transform:uppercase;letter-spacing:.3px;opacity:.8}.step-chip.next{color:var(--desk-blue)}.step-chip.done{color:#79bd89}.supplier-reference{font:11px monospace;margin:12px 0}.next-action{margin-top:18px}.step-caption{font:10px monospace;letter-spacing:1px;margin-bottom:12px;color:var(--desk-blue)}.order-confirm-form{display:grid;gap:12px;margin-top:18px}.order-confirm-form label{display:grid;gap:7px;font-size:12px}.order-confirm-form small{font-size:10px;opacity:.6}.order-confirm-form button{justify-self:start}.small-help{font-size:11px;line-height:1.7;opacity:.65;margin-top:10px}.tracking-editor{margin-top:18px}.tracking-editor summary{font:11px monospace;letter-spacing:.6px;cursor:pointer;margin-bottom:16px}.tracking-receipt{display:flex;gap:8px;flex-wrap:wrap;padding:12px;background:#79bd8910;border:1px solid #79bd8933;margin-top:14px;font-size:12px}.tracking-receipt a{margin-left:auto;text-decoration:underline}.undo-action{font-size:11px;text-decoration:underline;opacity:.65;margin-top:16px}.order-accounting{border-top:1px solid var(--color-border,#444);margin-top:20px;padding-top:16px;font-size:12px;line-height:1.8}.order-accounting summary{cursor:pointer;font-size:12px}.order-accounting p{margin:12px 0}.order-accounting>details{margin-top:14px}.digital-done{font-size:13px;color:#79bd89;margin:20px 0}.order-empty{padding:64px 20px;text-align:center;border:1px dashed var(--color-border,#444);margin:24px 0}.order-empty>b{font-size:42px;color:var(--desk-blue)}.order-empty h3{font-size:24px;margin:12px 0}.order-empty p{font-size:14px;opacity:.7}.loaded-count{font:11px monospace;opacity:.6;margin:18px 0}.desk-reports{border:1px solid var(--color-border,#444);padding:20px;margin-top:20px}.desk-reports>summary{font-size:14px;font-weight:700;cursor:pointer}.desk-reports .form-grid{margin-top:20px}.printify-actions{margin-top:16px;display:flex;gap:10px;flex-wrap:wrap}@media(max-width:1100px){.order-cards{grid-template-columns:1fr}}@media(max-width:600px){.order-scoreboard{grid-template-columns:repeat(2,minmax(0,1fr))}.order-scoreboard>div{padding:14px}.order-card{padding:18px}.order-desk-heading{align-items:flex-start}.order-desk-heading h2{font-size:28px}.delivery-card{display:block}.delivery-card button{margin-top:12px}.order-search>input{min-width:0;width:100%;flex-basis:100%}.order-lanes button{padding:9px 10px;font-size:11px}.order-total>strong{font-size:20px}}
</style>
